export const getVerifyCertificateUrl = (params: VerifyCertificateParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/verify?${stringifiedParams}` : `/api/verify`
}

export const verifyCertificate = async (params: VerifyCertificateParams, options?: RequestInit): Promise<VerifyResult> => {

  return customFetch<VerifyResult>(getVerifyCertificateUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





export const getVerifyCertificateQueryKey = (params?: VerifyCertificateParams,) => {
    return [
    `/api/verify`, ...(params ? [params] : [])
    ] as const;
    }


export const getVerifyCertificateQueryOptions = <TData = Awaited<ReturnType<typeof verifyCertificate>>, TError = ErrorType<NotFoundResponse>>(params: VerifyCertificateParams, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof verifyCertificate>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getVerifyCertificateQueryKey(params);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof verifyCertificate>>> = ({ signal }) => verifyCertificate(params, { signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof verifyCertificate>>, TError, TData> & { queryKey: QueryKey }
}

export type VerifyCertificateQueryResult = NonNullable<Awaited<ReturnType<typeof verifyCertificate>>>
export type VerifyCertificateQueryError = ErrorType<NotFoundResponse>



export function useVerifyCertificate<TData = Awaited<ReturnType<typeof verifyCertificate>>, TError = ErrorType<NotFoundResponse>>(
 params: VerifyCertificateParams, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof verifyCertificate>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getVerifyCertificateQueryOptions(params,options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return { ...query, queryKey: queryOptions.queryKey };
}







